3042849101.script:
(function() {
  'use strict';

  var wrap = document.querySelector('.hp-tdoc__scale-wrap');
  var DESIGN_WIDTH = 1440;
  var MIN_SCALE = 0.55;

  function updateScale() {
    var vw = window.innerWidth;
    var s = vw / DESIGN_WIDTH;
    if (s < MIN_SCALE) s = MIN_SCALE;
    if (s > 1) s = 1;
    wrap.style.setProperty('--hp-scale', s);
  }
  updateScale();
  var rt;
  window.addEventListener('resize', function() {
    clearTimeout(rt);
    rt = setTimeout(updateScale, 60);
  });

  var form         = document.getElementById('hp-tdoc-form');
  var orgInput     = document.getElementById('hp-tdoc-org');
  var emailInput   = document.getElementById('hp-tdoc-email');
  var siteInput    = document.getElementById('hp-tdoc-site');
  var policyInput  = document.getElementById('hp-tdoc-policy');
  var generateBtn  = document.getElementById('hp-tdoc-generate');
  var resetBtn     = document.getElementById('hp-tdoc-reset');
  var copyBtn      = document.getElementById('hp-tdoc-copy');
  var copyBtnText  = copyBtn.querySelector('.hp-tdoc__copy-btn-text');
  var outputEl     = document.getElementById('hp-tdoc-output');
  var goalsEl      = document.getElementById('hp-tdoc-goals');
  var addGoalBtn   = document.getElementById('hp-tdoc-add-goal');
  var copyTimeout  = null;
  var generated    = false;
  var goalCounter  = 0;

  var PURPOSE_OPTIONS = [
    'информирование Пользователя посредством отправки электронных писем',
    'заключение, исполнение и прекращение гражданско-правовых договоров',
    'предоставление доступа Пользователю к сервисам, информации и/или материалам, содержащимся на веб-сайте'
  ];

  var DATA_OPTIONS_TOP = [
    'фамилия, имя, отчество',
    'электронный адрес',
    'номера телефонов',
    'год, месяц, дата и место рождения',
    'фотографии'
  ];

  var DATA_OPTIONS_EXTRA = [
    'фамилия и имя',
    'имя',
    'свидетельство о гражданстве',
    'реквизиты документа, удостоверяющего личность',
    'идентификационный номер налогоплательщика, дата постановки его на учет, реквизиты свидетельства постановки на учет в налоговом органе',
    'номер свидетельства обязательного пенсионного страхования, дата регистрации в системе обязательного пенсионного страхования',
    'номер полиса обязательного медицинского страхования',
    'адрес фактического места проживания и регистрации по месту жительства и/или по месту пребывания',
    'сведения об образовании, профессии, специальности и квалификации, реквизиты документов об образовании',
    'сведения о семейном положении и составе семьи',
    'сведения об имущественном положении',
    'сведения о доходах',
    'сведения о задолженности',
    'сведения о занимаемых ранее должностях и стаже работы, воинской обязанности, воинском учете'
  ];

  var LEGAL_OPTIONS = [
    'уставные (учредительные) документы Оператора',
    'договоры, заключаемые между оператором и субъектом персональных данных'
  ];

  var PROCESSING_OPTIONS = [
    'Сбор, запись, систематизация, накопление, хранение, уничтожение и обезличивание персональных данных',
    'Отправка информационных писем на адрес электронной почты'
  ];

  function esc(str) {
    var d = document.createElement('div');
    d.appendChild(document.createTextNode(str));
    return d.innerHTML;
  }

  function uid() { return 'goal-' + (++goalCounter); }

  function buildCheckHtml(value, name) {
    return '<label class="hp-tdoc__check">' +
      '<input type="checkbox" name="' + name + '" value="' + esc(value) + '">' +
      '<span>' + esc(value) + '</span>' +
      '</label>';
  }

  function buildRadioHtml(value, name) {
    return '<label class="hp-tdoc__radio">' +
      '<input type="radio" name="' + name + '" value="' + esc(value) + '">' +
      '<span>' + esc(value) + '</span>' +
      '</label>';
  }

  function buildCustomInputHtml(label, id, placeholder) {
    return '<div class="hp-tdoc__custom">' +
      '<label class="hp-tdoc__custom-label" for="' + id + '">' + esc(label) + '</label>' +
      '<input type="text" id="' + id + '" placeholder="' + esc(placeholder) + '">' +
      '</div>';
  }

  function renumberGoals() {
    var blocks = goalsEl.querySelectorAll('.hp-tdoc__goal');
    for (var i = 0; i < blocks.length; i++) {
      var block = blocks[i];
      var titleEl = block.querySelector('.hp-tdoc__goal-title');
      if (titleEl) {
        titleEl.innerHTML = '<span class="hp-tdoc__goal-number">' + (i + 1) + '</span>Цель №' + (i + 1);
      }
      var actions = block.querySelector('.hp-tdoc__goal-actions');
      if (actions) {
        if (i === 0) actions.style.display = 'none';
        else actions.style.display = 'flex';
      }
    }
  }

  function buildGoalBlock() {
    var id = uid();
    var purposeName = id + '-purpose';
    var dataName    = id + '-data';
    var dataExtraName = id + '-data-extra';
    var legalName   = id + '-legal';
    var procName    = id + '-proc';
    var customPurposeId = id + '-custom-purpose';
    var customDataId    = id + '-custom-data';
    var customLegalId   = id + '-custom-legal';
    var customProcId    = id + '-custom-proc';

    var purposeRadios = '';
    for (var i = 0; i < PURPOSE_OPTIONS.length; i++) {
      purposeRadios += buildRadioHtml(PURPOSE_OPTIONS[i], purposeName);
    }

    var dataTopHtml = '';
    for (var i = 0; i < DATA_OPTIONS_TOP.length; i++) {
      dataTopHtml += buildCheckHtml(DATA_OPTIONS_TOP[i], dataName);
    }
    var dataExtraHtml = '';
    for (var i = 0; i < DATA_OPTIONS_EXTRA.length; i++) {
      dataExtraHtml += buildCheckHtml(DATA_OPTIONS_EXTRA[i], dataExtraName);
    }

    var legalHtml = '';
    for (var i = 0; i < LEGAL_OPTIONS.length; i++) {
      legalHtml += buildCheckHtml(LEGAL_OPTIONS[i], legalName);
    }

    var procHtml = '';
    for (var i = 0; i < PROCESSING_OPTIONS.length; i++) {
      procHtml += buildCheckHtml(PROCESSING_OPTIONS[i], procName);
    }

    var extraId = id + '-extra';

    var block = document.createElement('div');
    block.className = 'hp-tdoc__goal';
    block.setAttribute('data-goal', id);
    block.innerHTML =
      '<div class="hp-tdoc__goal-header">' +
        '<div class="hp-tdoc__goal-title">Цель №1</div>' +
      '</div>' +

      '<div class="hp-tdoc__subsection">' +
        '<span class="hp-tdoc__sublabel">Укажите цель обработки персональных данных:</span>' +
        '<p class="hp-tdoc__subhint">Можно выбрать только один вариант</p>' +
        '<div class="hp-tdoc__radio-group">' + purposeRadios + '</div>' +
        buildCustomInputHtml('Свой вариант', customPurposeId, 'Опишите свою цель обработки') +
      '</div>' +

      '<div class="hp-tdoc__subsection">' +
        '<span class="hp-tdoc__sublabel">Отметьте данные, которые вы собираете для этой цели:</span>' +
        '<p class="hp-tdoc__subhint">Можно выбрать несколько</p>' +
        '<div class="hp-tdoc__checkbox-group">' + dataTopHtml + '</div>' +
        '<button type="button" class="hp-tdoc__toggle-extra" data-toggle-btn="' + extraId + '">' +
          '<span>Ещё пункты…</span>' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>' +
        '</button>' +
        '<div class="hp-tdoc__extra-list" id="' + extraId + '" data-open="false">' + dataExtraHtml + '</div>' +
        buildCustomInputHtml('Свой вариант', customDataId, 'Опишите данные') +
      '</div>' +

      '<div class="hp-tdoc__subsection">' +
        '<span class="hp-tdoc__sublabel">Укажите правовые основания обработки персональных данных в рамках этой цели:</span>' +
        '<p class="hp-tdoc__subhint">Можно выбрать несколько</p>' +
        '<div class="hp-tdoc__checkbox-group">' + legalHtml + '</div>' +
        buildCustomInputHtml('Свой вариант', customLegalId, 'Опишите правовое основание') +
      '</div>' +

      '<div class="hp-tdoc__subsection">' +
        '<span class="hp-tdoc__sublabel">Укажите виды обработки персональных данных в рамках этой цели:</span>' +
        '<p class="hp-tdoc__subhint">Можно выбрать несколько</p>' +
        '<div class="hp-tdoc__checkbox-group">' + procHtml + '</div>' +
        buildCustomInputHtml('Свой вариант', customProcId, 'Опишите вид обработки') +
      '</div>' +

      '<div class="hp-tdoc__goal-actions" style="display:none;">' +
        '<button type="button" class="hp-tdoc__goal-delete" data-remove-goal>' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
            '<polyline points="3 6 5 6 21 6"></polyline>' +
            '<path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"></path>' +
          '</svg>' +
          'Удалить эту цель' +
        '</button>' +
      '</div>';

    goalsEl.appendChild(block);
    renumberGoals();
    return block;
  }

  function checkedValues(container, name) {
    var cbs = container.querySelectorAll('input[type="checkbox"][name="' + name + '"]');
    var arr = [];
    for (var i = 0; i < cbs.length; i++) {
      if (cbs[i].checked) arr.push(cbs[i].value);
    }
    return arr;
  }

  function checkedRadio(container, name) {
    var r = container.querySelector('input[type="radio"][name="' + name + '"]:checked');
    return r ? r.value : '';
  }

  function customValue(id) {
    var el = document.getElementById(id);
    return el ? el.value.trim() : '';
  }

  function slot(input, placeholder, linkType) {
    var v = input.value.trim();
    if (generated && v) {
      var attrs = 'class="hp-tdoc__filled"';
      if (linkType) {
        var href = '';
        if (linkType === 'mailto') href = 'mailto:' + v;
        else if (linkType === 'url') {
          var domain = v.replace(/^https?:\/\//i, '');
          href = 'https://' + domain;
        }
        attrs = 'class="hp-tdoc__filled hp-tdoc__filled--link" data-hp-href="' + esc(href) + '"';
      }
      return '<span ' + attrs + '>' + esc(v) + '</span>';
    }
    return '<span class="hp-tdoc__placeholder">' + placeholder + '</span>';
  }

  function attachLinks() {
    var spans = outputEl.querySelectorAll('.hp-tdoc__filled--link');
    for (var i = 0; i < spans.length; i++) {
      var span = spans[i];
      var href = span.getAttribute('data-hp-href');
      if (!href) continue;
      var a = document.createElement('a');
      a.href = href;
      a.className = 'hp-tdoc__link';
      if (href.indexOf('mailto:') !== 0) { a.target = '_blank'; a.rel = 'noopener'; }
      a.textContent = span.textContent;
      span.textContent = '';
      span.appendChild(a);
    }
  }

  function getGoalsData() {
    var blocks = goalsEl.querySelectorAll('.hp-tdoc__goal');
    var arr = [];
    for (var i = 0; i < blocks.length; i++) {
      var b = blocks[i];
      var id = b.getAttribute('data-goal');

      var purposeArr = [];
      var radioPurpose = checkedRadio(b, id + '-purpose');
      if (radioPurpose) purposeArr.push(radioPurpose);
      var purposeCustom = customValue(id + '-custom-purpose');
      if (purposeCustom) purposeArr.push(purposeCustom);

      var dataArr = checkedValues(b, id + '-data').concat(checkedValues(b, id + '-data-extra'));
      var dcu = customValue(id + '-custom-data');
      if (dcu) dataArr.push(dcu);

      var legalArr = checkedValues(b, id + '-legal');
      var lcu = customValue(id + '-custom-legal');
      if (lcu) legalArr.push(lcu);

      var procArr = checkedValues(b, id + '-proc');
      var pcu = customValue(id + '-custom-proc');
      if (pcu) procArr.push(pcu);

      arr.push({ purpose: purposeArr, data: dataArr, legal: legalArr, proc: procArr });
    }
    return arr;
  }

  function renderListCell(values, placeholder) {
    if (generated && values.length) {
      var html = '';
      for (var i = 0; i < values.length; i++) {
        html += '<span class="hp-tdoc__filled">' + esc(values[i]) + '</span>' + (i < values.length - 1 ? '<br>' : '');
      }
      return html;
    }
    return '<span class="hp-tdoc__placeholder">' + placeholder + '</span>';
  }

  function renderTemplate() {
    var orgSlot    = slot(orgInput,    'ФИО или название организации', null);
    var emailSlot  = slot(emailInput,  'email оператора',              'mailto');
    var siteSlot   = slot(siteInput,   'адрес сайта',                  'url');
    var policySlot = slot(policyInput, 'адрес страницы с политикой',   'url');

    var goals = getGoalsData();
    var html = '';

    html += '<div class="h1">Политика в отношении обработки персональных данных</div>';

    html += '<div class="h2">1. Общие положения</div>';
    html += '<p>Настоящая политика обработки персональных данных составлена в соответствии с требованиями Федерального закона от 27.07.2006. № 152-ФЗ «О персональных данных» (далее — Закон о персональных данных) и определяет порядок обработки персональных данных и меры по обеспечению безопасности персональных данных, предпринимаемые ' + orgSlot + ' (далее — Оператор).</p>';
    html += '<p>1.1. Оператор ставит своей важнейшей целью и условием осуществления своей деятельности соблюдение прав и свобод человека и гражданина при обработке его персональных данных, в том числе защиты прав на неприкосновенность частной жизни, личную и семейную тайну.</p>';
    html += '<p>1.2. Настоящая политика Оператора в отношении обработки персональных данных (далее — Политика) применяется ко всей информации, которую Оператор может получить о посетителях веб-сайта ' + siteSlot + '.</p>';

    html += '<div class="h2">2. Основные понятия, используемые в Политике</div>';
    html += '<p>2.1. Автоматизированная обработка персональных данных — обработка персональных данных с помощью средств вычислительной техники.</p>';
    html += '<p>2.2. Блокирование персональных данных — временное прекращение обработки персональных данных (за исключением случаев, если обработка необходима для уточнения персональных данных).</p>';
    html += '<p>2.3. Веб-сайт — совокупность графических и информационных материалов, а также программ для ЭВМ и баз данных, обеспечивающих их доступность в сети интернет по сетевому адресу ' + siteSlot + '.</p>';
    html += '<p>2.4. Информационная система персональных данных — совокупность содержащихся в базах данных персональных данных и обеспечивающих их обработку информационных технологий и технических средств.</p>';
    html += '<p>2.5. Обезличивание персональных данных — действия, в результате которых невозможно определить без использования дополнительной информации принадлежность персональных данных конкретному Пользователю или иному субъекту персональных данных.</p>';
    html += '<p>2.6. Обработка персональных данных — любое действие (операция) или совокупность действий (операций), совершаемых с использованием средств автоматизации или без использования таких средств с персональными данными, включая сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление, уничтожение персональных данных.</p>';
    html += '<p>2.7. Оператор — государственный орган, муниципальный орган, юридическое или физическое лицо, самостоятельно или совместно с другими лицами организующие и/или осуществляющие обработку персональных данных, а также определяющие цели обработки персональных данных, состав персональных данных, подлежащих обработке, действия (операции), совершаемые с персональными данными.</p>';
    html += '<p>2.8. Персональные данные — любая информация, относящаяся прямо или косвенно к определенному или определяемому Пользователю веб-сайта ' + siteSlot + '.</p>';
    html += '<p>2.9. Персональные данные, разрешенные субъектом персональных данных для распространения, — персональные данные, доступ неограниченного круга лиц к которым предоставлен субъектом персональных данных путем дачи согласия на обработку персональных данных, разрешенных субъектом персональных данных для распространения в порядке, предусмотренном Законом о персональных данных (далее — персональные данные, разрешенные для распространения).</p>';
    html += '<p>2.10. Пользователь — любой посетитель веб-сайта ' + siteSlot + '.</p>';
    html += '<p>2.11. Предоставление персональных данных — действия, направленные на раскрытие персональных данных определенному лицу или определенному кругу лиц.</p>';
    html += '<p>2.12. Распространение персональных данных — любые действия, направленные на раскрытие персональных данных неопределенному кругу лиц (передача персональных данных) или на ознакомление с персональными данными неограниченного круга лиц, в том числе обнародование персональных данных в средствах массовой информации, размещение в информационно-телекоммуникационных сетях или предоставление доступа к персональным данным каким-либо иным способом.</p>';
    html += '<p>2.13. Трансграничная передача персональных данных — передача персональных данных на территорию иностранного государства органу власти иностранного государства, иностранному физическому или иностранному юридическому лицу.</p>';
    html += '<p>2.14. Уничтожение персональных данных — любые действия, в результате которых персональные данные уничтожаются безвозвратно с невозможностью дальнейшего восстановления содержания персональных данных в информационной системе персональных данных и/или уничтожаются материальные носители персональных данных.</p>';

    html += '<div class="h2">3. Основные права и обязанности Оператора</div>';
    html += '<p>3.1. Оператор имеет право:</p>';
    html += '<ul><li>получать от субъекта персональных данных достоверные информацию и/или документы, содержащие персональные данные;</li>';
    html += '<li>в случае отзыва субъектом персональных данных согласия на обработку персональных данных, а также, направления обращения с требованием о прекращении обработки персональных данных, Оператор вправе продолжить обработку персональных данных без согласия субъекта персональных данных при наличии оснований, указанных в Законе о персональных данных;</li>';
    html += '<li>самостоятельно определять состав и перечень мер, необходимых и достаточных для обеспечения выполнения обязанностей, предусмотренных Законом о персональных данных и принятыми в соответствии с ним нормативными правовыми актами, если иное не предусмотрено Законом о персональных данных или другими федеральными законами.</li></ul>';
    html += '<p>3.2. Оператор обязан:</p>';
    html += '<ul><li>предоставлять субъекту персональных данных по его просьбе информацию, касающуюся обработки его персональных данных;</li>';
    html += '<li>организовывать обработку персональных данных в порядке, установленном действующим законодательством РФ;</li>';
    html += '<li>отвечать на обращения и запросы субъектов персональных данных и их законных представителей в соответствии с требованиями Закона о персональных данных;</li>';
    html += '<li>сообщать в уполномоченный орган по защите прав субъектов персональных данных по запросу этого органа необходимую информацию в течение 10 дней с даты получения такого запроса;</li>';
    html += '<li>публиковать или иным образом обеспечивать неограниченный доступ к настоящей Политике в отношении обработки персональных данных;</li>';
    html += '<li>принимать правовые, организационные и технические меры для защиты персональных данных от неправомерного или случайного доступа к ним, уничтожения, изменения, блокирования, копирования, предоставления, распространения персональных данных, а также от иных неправомерных действий в отношении персональных данных;</li>';
    html += '<li>прекратить передачу (распространение, предоставление, доступ) персональных данных, прекратить обработку и уничтожить персональные данные в порядке и случаях, предусмотренных Законом о персональных данных;</li>';
