    } else if (!generated) {
      html += '<p><span class="hp-tdoc__placeholder">добавьте цели обработки в форме</span></p>';
    }

    html += '<div class="h2">7. Условия обработки персональных данных</div>';
    html += '<p>7.1. Обработка персональных данных осуществляется с согласия субъекта персональных данных на обработку его персональных данных.</p>';
    html += '<p>7.2. Обработка персональных данных необходима для достижения целей, предусмотренных международным договором Российской Федерации или законом, для осуществления возложенных законодательством Российской Федерации на оператора функций, полномочий и обязанностей.</p>';
    html += '<p>7.3. Обработка персональных данных необходима для осуществления правосудия, исполнения судебного акта, акта другого органа или должностного лица, подлежащих исполнению в соответствии с законодательством Российской Федерации об исполнительном производстве.</p>';
    html += '<p>7.4. Обработка персональных данных необходима для исполнения договора, стороной которого либо выгодоприобретателем или поручителем по которому является субъект персональных данных, а также для заключения договора по инициативе субъекта персональных данных или договора, по которому субъект персональных данных будет являться выгодоприобретателем или поручителем.</p>';
    html += '<p>7.5. Обработка персональных данных необходима для осуществления прав и законных интересов оператора или третьих лиц либо для достижения общественно значимых целей при условии, что при этом не нарушаются права и свободы субъекта персональных данных.</p>';
    html += '<p>7.6. Осуществляется обработка персональных данных, доступ неограниченного круга лиц к которым предоставлен субъектом персональных данных либо по его просьбе (далее — общедоступные персональные данные).</p>';
    html += '<p>7.7. Осуществляется обработка персональных данных, подлежащих опубликованию или обязательному раскрытию в соответствии с федеральным законом.</p>';

    html += '<div class="h2">8. Порядок сбора, хранения, передачи и других видов обработки персональных данных</div>';
    html += '<p>Безопасность персональных данных, которые обрабатываются Оператором, обеспечивается путем реализации правовых, организационных и технических мер, необходимых для выполнения в полном объеме требований действующего законодательства в области защиты персональных данных.</p>';
    html += '<p>8.1. Оператор обеспечивает сохранность персональных данных и принимает все возможные меры, исключающие доступ к персональным данным неуполномоченных лиц.</p>';
    html += '<p>8.2. Персональные данные Пользователя никогда, ни при каких условиях не будут переданы третьим лицам, за исключением случаев, связанных с исполнением действующего законодательства либо в случае, если субъектом персональных данных дано согласие Оператору на передачу данных третьему лицу для исполнения обязательств по гражданско-правовому договору.</p>';
    html += '<p>8.3. В случае выявления неточностей в персональных данных, Пользователь может актуализировать их самостоятельно, путем направления Оператору уведомление на адрес электронной почты Оператора ' + emailSlot + ' с пометкой «Актуализация персональных данных».</p>';
    html += '<p>8.4. Срок обработки персональных данных определяется достижением целей, для которых были собраны персональные данные, если иной срок не предусмотрен договором или действующим законодательством. Пользователь может в любой момент отозвать свое согласие на обработку персональных данных, направив Оператору уведомление посредством электронной почты на электронный адрес Оператора ' + emailSlot + ' с пометкой «Отзыв согласия на обработку персональных данных».</p>';
    html += '<p>8.5. Вся информация, которая собирается сторонними сервисами, в том числе платежными системами, средствами связи и другими поставщиками услуг, хранится и обрабатывается указанними лицами (Операторами) в соответствии с их Пользовательским соглашением и Политикой конфиденциальности. Субъект персональных данных и/или с указанными документами. Оператор не несет ответственность за действия треть лиц, в том числе указанных в настоящем пункте поставщиков услуг.</p>';
    html += '<p>8.6. Установленные субъектом персональных данных запреты на передачу (кроме предоставления доступа), а также на обработку или условия обработки (кроме получения доступа) персональных данных, разрешенных для распространения, не действуют в случаях обработки персональных данных в государственных, общественных и иных публичных интересах, определенных законодательством РФ.</p>';
    html += '<p>8.7. Оператор при обработке персональных данных обеспечивает конфиденциальность персональных данных.</p>';
    html += '<p>8.8. Оператор осуществляет хранение персональных данных в форме, позволяющей определить субъекта персональных данных, не дольше, чем этого требуют цели обработки персональных данных, если срок хранения персональных данных не установлен федеральным законом, договором, стороной которого, выгодоприобретателем или поручителем по которому является субъект персональных данных.</p>';
    html += '<p>8.9. Условием прекращения обработки персональных данных может являться достижение целей обработки персональных данных, истечение срока действия согласия субъекта персональных данных, отзыв согласия субъектом персональных данных или требование о прекращении обработки персональных данных, а также выявление неправомерной обработки персональных данных.</p>';

    html += '<div class="h2">9. Перечень действий, производимых Оператором с полученными персональными данными</div>';
    html += '<p>9.1. Оператор осуществляет сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление и уничтожение персональных данных.</p>';
    html += '<p>9.2. Оператор осуществляет автоматизированную обработку персональных данных с получением и/или передачей полученной информации по информационно-телекоммуникационным сетям или без таковой.</p>';

    html += '<div class="h2">10. Трансграничная передача персональных данных</div>';
    html += '<p>10.1. Оператор до начала осуществления деятельности по трансграничной передаче персональных данных обязан уведомить уполномоченный орган по защите прав субъектов персональных данных о своем намерении осуществлять трансграничную передачу персональных данных (такое уведомление направляется отдельно от уведомления о намерении осуществлять обработку персональных данных).</p>';
    html += '<p>10.2. Оператор до подачи вышеуказанного уведомления, обязан получить от органов власти иностранного государства, иностранных физических лиц, иностранных юридических лиц, которым планируется трансграничная передача персональных данных, соответствующие сведения.</p>';

    html += '<div class="h2">11. Конфиденциальность персональных данных</div>';
    html += '<p>Оператор и иные лица, получившие доступ к персональным данным, обязаны не раскрывать третьим лицам и не распространять персональные данные без согласия субъекта персональных данных, если иное не предусмотрено федеральным законом.</p>';

    html += '<div class="h2">12. Заключительные положения</div>';
    html += '<p>12.1. Пользователь может получить любые разъ разъяснения по интересующим вопросам, касающимся обработки его персональных данных, обратившись к Оператору с помощью электронной почты ' + emailSlot + '.</p>';
    html += '<p>12.2. В данном документе будут отражены любые изменения политики обработки персональных данных Оператором. Политика действует бессрочно до замены ее новой версией.</p>';
    html += '<p>12.3. Актуальная версия Политики в свободном доступе расположена в сети Интернет по адресу ' + policySlot + '.</p>';

    outputEl.innerHTML = '<div class="hp-tdoc__generated">' + html + '</div>';
    attachLinks();
  }

  function handleGenerate() {
    if (!orgInput.value.trim() && !emailInput.value.trim() && !siteInput.value.trim() && !policyInput.value.trim()) {
      orgInput.focus();
      return;
    }
    generated = true;
    renderTemplate();
  }

  function handleReset() {
    orgInput.value = '';
    emailInput.value = '';
    siteInput.value = '';
    policyInput.value = '';
    goalsEl.innerHTML = '';
    goalCounter = 0;
    buildGoalBlock();
    generated = false;
    renderTemplate();
    orgInput.focus();
  }

  function copyToClipboard() {
    var el = outputEl.querySelector('.hp-tdoc__generated');
    if (!el) return;
    var text = el.innerText || el.textContent;
    if (!text) return;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(showCopied).catch(function() { fallbackCopy(text); });
    } else {
      fallbackCopy(text);
    }
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;left:-9999px;top:-9999px;';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); showCopied(); } catch (e) {}
    document.body.removeChild(ta);
  }

  function showCopied() {
    if (copyTimeout) clearTimeout(copyTimeout);
    copyBtn.classList.add('hp-tdoc__copy-btn--copied');
    copyBtnText.textContent = 'Скопировано!';
    copyTimeout = setTimeout(function() {
      copyBtn.classList.remove('hp-tdoc__copy-btn--copied');
      copyBtnText.textContent = 'Копировать текст';
    }, 2000);
  }

  generateBtn.addEventListener('click', handleGenerate);
  resetBtn.addEventListener('click', handleReset);
  copyBtn.addEventListener('click', copyToClipboard);

  addGoalBtn.addEventListener('click', function() {
    var newBlock = buildGoalBlock();
    if (generated) renderTemplate();
    newBlock.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });

  goalsEl.addEventListener('click', function(e) {
    var remBtn = e.target.closest('[data-remove-goal]');
    if (remBtn) {
      var block = remBtn.closest('.hp-tdoc__goal');
      if (!block) return;
      if (goalsEl.querySelectorAll('.hp-tdoc__goal').length <= 1) return;
      block.parentNode.removeChild(block);
      renumberGoals();
      if (generated) renderTemplate();
      return;
    }
    var togBtn = e.target.closest('[data-toggle-btn]');
    if (togBtn) {
      var targetId = togBtn.getAttribute('data-toggle-btn');
      var target = document.getElementById(targetId);
      if (!target) return;
      var open = target.getAttribute('data-open') === 'true';
      target.setAttribute('data-open', open ? 'false' : 'true');
      togBtn.classList.toggle('hp-tdoc__toggle-extra--open', !open);
      togBtn.querySelector('span').textContent = open ? 'Ещё пункты…' : 'Скрыть пункты';
    }
  });

  function delegateChange(root, handler) {
    root.addEventListener('change', function(e) {
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA')) handler();
    });
    root.addEventListener('input', function(e) {
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA')) handler();
    });
  }

  delegateChange(form, function() { if (generated) renderTemplate(); });

  buildGoalBlock();
  renderTemplate();
})();

