    utm_medium: { title: "utm_medium — тип рекламы", body: "В этом параметре рекомендуется использовать устоявшиеся значения, например: cpc (cost per click) — это контекстная реклама, display — баннерная реклама с оплатой за показы, social_cpc — реклама в соцсетях с оплатой за клик.\n\nЗачем нужен: Чтобы определить тип кампании или рекламы.\n\nПримеры:\nutm_medium=organic – бесплатный переход\nutm_medium=cpc – контекстная реклама\nutm_medium=email — рассылка\nutm_medium=social — социальные сети\nutm_medium=banner — медийная реклама\nutm_medium=cpa — другая реклама" },
    utm_campaign: { title: "utm_campaign — название кампании", body: "Этот обязательный параметр можно задать произвольно.\n\nЗачем нужен: Позволит вам отличить одну рекламную кампанию от другой в статистике.\n\nПримеры:\nutm_campaign=mebel_dlya_doma — рекламная кампания мебели для дома" },
    utm_content: { title: "utm_content — дополнительная информация", body: "Часто используется как пометка для объявления внутри рекламной кампании. Название можно задать произвольно, удобнее всего использовать важные характеристики объявления — подкатегория товара или услуги, тип самого объявления и т. п.\n\nПримеры:\nutm_content=zero_block240×60 — баннер 240 на 60 про Zero блок\nutm_content=zero_block_text — текстовое объявление про Zero блок" },
    utm_term: { title: "utm_term — ключевое слово", body: "Ключевое слово, с которого начался показ объявления. Этот обязательный параметр можно задать произвольно.\n\nЗачем нужен: Позволит вам отличить одну рекламную кампанию от другой в статистике." }
  };

  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('utmg__tooltip-btn')) {
      const infoKey = e.target.getAttribute('data-info');
      const data = tooltips[infoKey];
      if (data) {
        popupTitle.innerText = data.title;
        popupBody.innerText = data.body;
        popup.classList.add('is-open');
      }
    }
  });

  document.getElementById('popup-close').addEventListener('click', () => popup.classList.remove('is-open'));
  popup.addEventListener('click', (e) => { if(e.target === popup) popup.classList.remove('is-open'); });

  const presets = {
    google: {
      utm_source: { val: 'google', hint: '' },
      utm_medium: { val: 'cpc', hint: '' },
      utm_campaign: { val: '{network}', hint: 'Вместо {network} Google Ads подставит \'g\' (поиск), \'s\' (поисковый партнер) или \'d\' (КМС)' },
      utm_content: { val: '{creative}', hint: 'Вместо {creative} Google Ads автоматически подставит ID объявления' },
      utm_term: { val: '{keyword}', hint: 'Вместо {keyword} Google Ads автоматически подставит ключевое слово' }
    },
    yandex: {
      utm_source: { val: 'yandex', hint: '' },
      utm_medium: { val: 'cpc', hint: '' },
      utm_campaign: { val: '{campaign_id}', hint: 'Вместо {campaign_id} Яндекс.Директ автоматически подставит ID кампании' },
      utm_content: { val: '{ad_id}', hint: 'Вместо {ad_id} Яндекс.Директ автоматически подставит ID объявления' },
      utm_term: { val: '{keyword}', hint: 'Вместо {keyword} Яндекс.Директ автоматически подставит ключевое слово' }
    },
    vk: {
      utm_source: { val: 'vkontakte', hint: '' },
      utm_medium: { val: 'cpc', hint: '' },
      utm_campaign: { val: '{campaign_id}', hint: 'Вместо {campaign_id} Вконтакте автоматически подставит ID объявления' },
      utm_content: { val: '{ad_id}', hint: 'Вместо {ad_id} Вконтакте автоматически подставит ID объявления' },
      utm_term: { val: 'free, -30%, registration', hint: '' }
    },
    target: {
      utm_source: { val: 'mycom', hint: '' },
      utm_medium: { val: 'cpc', hint: '' },
      utm_campaign: { val: '{campaign_id}', hint: 'Вместо {campaign_id} Target My.com автоматически подставит ID кампании' },
      utm_content: { val: '{banner_id}', hint: 'Вместо {banner_id} Target My.com автоматически подставит ID баннера' },
      utm_term: { val: '{geo}.{gender}.{age}', hint: 'Вместо {geo}.{gender}.{age} Target My.com автоматически подставит ID региона, пол и возраст кликнувшего по рекламе' }
    },
    custom: {
      utm_source: { val: '', hint: '' }, utm_medium: { val: '', hint: '' },
      utm_campaign: { val: '', hint: '' }, utm_content: { val: '', hint: '' }, utm_term: { val: '', hint: '' }
    }
  };

  container.querySelectorAll('input[name="traffic"]').forEach(radio => {
    radio.addEventListener('change', (e) => {
      const source = e.target.value;
      const data = presets[source];
      if (data) {
        inputs.forEach(input => {
          const key = input.dataset.param;
          if (data[key]) {
            input.value = data[key].val;
            const hintEl = container.querySelector(`[data-hint="${key}"]`);
            if (hintEl) hintEl.textContent = data[key].hint;
          }
        });
        update();
      }
    });
  });

  function transliterate(str) {
    if (!translitCheck.checked) return str;
    const map = {'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'yo','ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts','ч':'ch','ш':'sh','щ':'sch','ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'};
    return str.split('').map(char => map[char.toLowerCase()] || char).join('');
  }

  function update() {
    let url = urlInput.value.trim();
    if (url && !url.startsWith('http')) url = 'https://' + url;
    let params = [];
    inputs.forEach(input => {
      let val = input.value.trim();
      if (val) { 
        let encoded = encodeURIComponent(transliterate(val)).replace(/%7B/g, '{').replace(/%7D/g, '}');
        params.push(`${input.dataset.param}=${encoded}`); 
      }
    });
    const final = params.length > 0 ? (url.includes('?') ? '&' : '?') + params.join('&') : '';
    resultInput.value = url + final;
  }

  container.addEventListener('input', update);
  translitCheck.addEventListener('change', update);

  btnCopy.addEventListener('click', async () => {
    const textToCopy = resultInput.value;
    if (!textToCopy) return;

    try {
      await navigator.clipboard.writeText(textToCopy);
      const originalText = btnCopy.innerText;
      btnCopy.innerText = 'Скопировано!';
      setTimeout(() => btnCopy.innerText = originalText, 2000);
    } catch (err) {
      console.error('Ошибка при копировании:', err);
    }
  });
})();

