(function() {
  const form = document.querySelector('.vb-qiz__form');
  const btn = form.querySelector('.vb-qiz__btn-calc');
  const resetBtn = form.querySelector('.vb-qiz__btn-reset');
  const results = {
    free: document.getElementById('res-free'),
    personal: document.getElementById('res-personal'),
    business: document.getElementById('res-business')
  };

  btn.addEventListener('click', function() {
    if (!form.checkValidity()) {
      form.reportValidity();
      return;
    }

    const q1 = form.querySelector('[name="q1"]:checked')?.value;
    const q2 = form.querySelector('[name="q2"]:checked')?.value;
    const q3Nodes = form.querySelectorAll('[name="q3"]:checked');
    const q4 = form.querySelector('[name="q4"]:checked')?.value;

    const isBusiness = (q1 === 'business' || q4 === 'business');
    const isPersonal = (q2 === 'paid' || q3Nodes.length > 0);

    let activeKey = 'free';
    if (isBusiness) {
      activeKey = 'business';
    } else if (isPersonal) {
      activeKey = 'personal';
    }

    Object.keys(results).forEach(key => {
      results[key].style.display = (key === activeKey) ? 'block' : 'none';
    });
  });

  resetBtn.addEventListener('click', function() {
    Object.keys(results).forEach(key => {
      results[key].style.display = 'none';
    });
  });
})();
